#pragma once

/** 正常联网状态下提供的 Web 管理页面。 */
static const char g_web_management_page[] =
"<!doctype html><html lang=\"zh-CN\"><head><meta charset=\"utf-8\">"
"<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>短信转发器</title>"
"<style>:root{font-family:system-ui,sans-serif;color:#18212f;background:#eef2f7}body{margin:0}.wrap{max-width:920px;margin:auto;padding:18px}"
"h1{font-size:1.5rem}.card{background:#fff;border-radius:12px;padding:16px;margin:12px 0;box-shadow:0 2px 12px #15223818}"
".grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:10px}label{display:block;font-size:.85rem;color:#58657a}"
"input,select,textarea,button{box-sizing:border-box;width:100%;padding:10px;margin-top:5px;border:1px solid #cad2df;border-radius:7px}"
"button{background:#1769e0;color:#fff;border:0;cursor:pointer}.danger{background:#bb2d3b}.muted{color:#657187;font-size:.9rem}"
"#app{display:none}pre{white-space:pre-wrap;background:#101722;color:#d8e2ef;padding:12px;max-height:300px;overflow:auto}</style></head>"
"<body><div class=\"wrap\"><h1>📱 ESP-IDF 短信转发器（C）</h1>"
"<section id=\"login\" class=\"card\"><h2>登录</h2><label>账号<input id=\"loginUser\" value=\"admin\"></label>"
"<label>密码<input id=\"loginPass\" type=\"password\"></label><button onclick=\"loginNow()\">登录</button><p id=\"loginMsg\"></p></section>"
"<main id=\"app\"><section class=\"card\"><h2>状态</h2><div id=\"status\" class=\"grid\"></div><p id=\"force\" class=\"muted\"></p></section>"
"<section class=\"card\"><h2>安全设置</h2><label>新管理密码（至少10位）<input id=\"newPass\" type=\"password\"></label>"
"<button onclick=\"savePassword()\">更新密码</button></section>"
"<section class=\"card\"><h2>通知与远程命令</h2><div class=\"grid\">"
"<label>SMTP服务器<input id=\"smtpServer\"></label><label>SMTP端口<select id=\"smtpPort\"><option>465</option><option>587</option></select></label>"
"<label>SMTP账号<input id=\"smtpUser\"></label><label>SMTP授权码（留空保持）<input id=\"smtpPass\" type=\"password\"></label>"
"<label>接收邮箱<input id=\"smtpTo\"></label><label>管理员号码<input id=\"adminPhone\"></label>"
"<label><input id=\"adminEnabled\" type=\"checkbox\">启用管理员短信命令</label></div>"
"<label>号码黑名单（每行一个）<textarea id=\"blacklist\"></textarea></label><div id=\"channels\"></div>"
"<button onclick=\"saveConfig()\">保存通知配置</button></section>"
"<section class=\"card\"><h2>发送短信</h2><div class=\"grid\"><label>号码<input id=\"phone\" maxlength=\"20\"></label>"
"<label>内容<textarea id=\"message\" maxlength=\"2048\"></textarea></label></div><button onclick=\"sendSms()\">加入发送队列</button></section>"
"<section class=\"card\"><h2>安全查询</h2><div class=\"grid\"><select id=\"at\"><option>ATI</option><option>AT+CSQ</option>"
"<option>AT+CESQ</option><option>AT+CEREG?</option><option>AT+CGACT?</option><option>AT+ICCID</option><option>AT+GSN</option>"
"<option>AT+COPS?</option><option>AT+CFUN?</option></select><button onclick=\"queryAt()\">执行只读查询</button></div></section>"
"<section class=\"card\"><h2>控制</h2><div class=\"grid\"><button onclick=\"post('/api/modem/restart',{mode:'soft'})\">软重启模组</button>"
"<button class=\"danger\" onclick=\"post('/api/modem/restart',{mode:'hard'})\">硬重启模组</button>"
"<button onclick=\"post('/api/wifi/reconnect',{})\">重连Wi-Fi</button><button class=\"danger\" onclick=\"post('/api/system/restart',{})\">重启ESP32</button></div>"
"<p class=\"muted\">固件永久禁止PDP激活、蜂窝Ping和数据拨号。</p></section>"
"<section class=\"card\"><h2>日志</h2><button onclick=\"logsNow()\">刷新</button><pre id=\"logs\"></pre></section></main></div>"
"<script>let csrf='';async function api(path,opt={}){opt.headers=Object.assign({'Content-Type':'application/json'},opt.headers||{});"
"if(csrf)opt.headers['X-CSRF-Token']=csrf;let r=await fetch(path,opt),t=await r.text(),d={};try{d=JSON.parse(t)}catch(e){d={message:t}}"
"if(!r.ok)throw Error(d.message||('HTTP '+r.status));return d}async function loginNow(){try{let d=await api('/api/session',{method:'POST',body:JSON.stringify({username:loginUser.value,password:loginPass.value})});"
"csrf=d.csrf;login.style.display='none';app.style.display='block';refresh()}catch(e){loginMsg.textContent=e.message}}"
"const types=['停用','POST JSON','Bark','GET','钉钉','PushPlus','Server酱','自定义','飞书','Gotify','Telegram'];"
"function esc(v){return String(v).replace(/[&<>\"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[x]))}"
"function channelHtml(c,i){return '<div class=\"card\"><b>通道 '+(i+1)+'</b><label><input id=\"c'+i+'e\" type=\"checkbox\" '+(c.enabled?'checked':'')+'>启用</label>'"
"+'<label>类型<select id=\"c'+i+'t\">'+types.map((x,n)=>'<option value=\"'+n+'\" '+(c.type==n?'selected':'')+'>'+x+'</option>').join('')+'</select></label>'"
"+'<label>名称<input id=\"c'+i+'n\" value=\"'+esc(c.name||'')+'\"></label><label>URL<input id=\"c'+i+'u\" value=\"'+esc(c.url||'')+'\"></label>'"
"+'<label>Key1/Secret（留空保持）<input id=\"c'+i+'k1\" type=\"password\"></label><label>Key2/Token（留空保持）<input id=\"c'+i+'k2\" type=\"password\"></label>'"
"+'<label>自定义请求体（留空保持）<textarea id=\"c'+i+'b\"></textarea></label></div>'}"
"async function loadConfig(){let c=await api('/api/config');smtpServer.value=c.smtp_server||'';smtpPort.value=c.smtp_port||465;smtpUser.value=c.smtp_user||'';"
"smtpTo.value=c.smtp_recipient||'';adminPhone.value=c.admin_phone||'';adminEnabled.checked=!!c.admin_commands_enabled;blacklist.value=c.number_blacklist||'';"
"channels.innerHTML=(c.push_channels||[]).map(channelHtml).join('')}async function refresh(){let d=await api('/api/status');status.innerHTML=Object.entries(d).map(x=>'<div><b>'+x[0]+'</b><br>'+String(x[1])+'</div>').join('');"
"force.textContent=d.password_change_required?'请在设置中重新设置管理密码。':'';await loadConfig()}async function post(p,b){try{let d=await api(p,{method:'POST',body:JSON.stringify(b)});alert(d.message||('任务 '+d.job_id))}catch(e){alert(e.message)}}"
"function sendSms(){post('/api/sms',{phone:phone.value,message:message.value})}function queryAt(){post('/api/at/query',{command:at.value})}"
"async function savePassword(){try{await api('/api/config',{method:'POST',body:JSON.stringify({web_password:newPass.value})});newPass.value='';refresh();alert('密码已更新')}catch(e){alert(e.message)}}"
"async function saveConfig(){let cs=[0,1,2,3,4].map(i=>({enabled:document.getElementById('c'+i+'e').checked,type:+document.getElementById('c'+i+'t').value,"
"name:document.getElementById('c'+i+'n').value,url:document.getElementById('c'+i+'u').value,key1:document.getElementById('c'+i+'k1').value,"
"key2:document.getElementById('c'+i+'k2').value,custom_body:document.getElementById('c'+i+'b').value}));try{await api('/api/config',{method:'POST',body:JSON.stringify({"
"smtp_server:smtpServer.value,smtp_port:+smtpPort.value,smtp_user:smtpUser.value,smtp_password:smtpPass.value,smtp_recipient:smtpTo.value,admin_phone:adminPhone.value,"
"admin_commands_enabled:adminEnabled.checked,number_blacklist:blacklist.value,push_channels:cs})});smtpPass.value='';await loadConfig();alert('配置已保存')}catch(e){alert(e.message)}}"
"async function logsNow(){let d=await api('/api/logs');logs.textContent=d.lines.join('\\n')}</script></body></html>";

/** 开放式 AP 配网状态下提供的登录与 Wi-Fi 配置页面。 */
static const char g_web_provision_page[] =
"<!doctype html><html lang=\"zh-CN\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1,viewport-fit=cover\">"
"<title>短信转发器·配网</title><style>:root{font-family:system-ui,-apple-system,sans-serif;color:#152033;background:#edf3fb;color-scheme:light}*{box-sizing:border-box}"
"body{margin:0;min-height:100vh;background:linear-gradient(145deg,#e8f2ff,#f7f9fc 55%,#eaf7f3)}.wrap{width:min(100%,500px);margin:auto;padding:36px 18px}"
".brand{display:flex;align-items:center;gap:12px;margin:0 4px 20px}.icon{display:grid;place-items:center;width:48px;height:48px;border-radius:15px;background:#1769e0;color:#fff;font-size:25px;box-shadow:0 8px 24px #1769e044}"
"h1{font-size:1.45rem;margin:0}.sub{color:#657187;font-size:.88rem;margin:3px 0 0}.card{background:#fffffff2;border:1px solid #fff;border-radius:18px;padding:22px;box-shadow:0 12px 36px #24466b1a}"
".step{color:#1769e0;font-size:.78rem;font-weight:700;letter-spacing:.08em}h2{font-size:1.15rem;margin:7px 0 5px}.hint,.msg{color:#657187;font-size:.88rem;line-height:1.55}label{display:block;margin:15px 0 0;font-size:.88rem;color:#43516a}"
"input,select,button{width:100%;padding:12px 13px;margin-top:6px;border:1px solid #c9d4e3;border-radius:10px;font:inherit;background:#fff}input:focus,select:focus{outline:3px solid #1769e022;border-color:#1769e0}"
"button{margin-top:18px;border:0;background:#1769e0;color:#fff;font-weight:700;cursor:pointer}button:disabled{opacity:.55}.msg{min-height:22px;margin-bottom:0}.fallback{text-align:center;margin-top:16px;color:#718096;font-size:.78rem}#setup{display:none}</style></head>"
"<body><div class=\"wrap\"><div class=\"brand\"><div class=\"icon\">📶</div><div><h1>短信转发器</h1><p class=\"sub\">ESP32-C3 安全配网门户</p></div></div>"
"<section id=\"login\" class=\"card\"><div class=\"step\">第 1 步 / 共 2 步</div><h2>登录设备</h2><p class=\"hint\">当前热点不需 Wi-Fi 密码；管理密码用于保护设备配置。</p>"
"<label>管理账号<input id=\"u\" value=\"admin\" autocomplete=\"username\"></label><label>管理密码<input id=\"a\" type=\"password\" autocomplete=\"current-password\" autofocus></label>"
"<button id=\"lb\" onclick=\"loginNow()\">登录并继续</button><p id=\"lm\" class=\"msg\"></p></section>"
"<section id=\"setup\" class=\"card\"><div class=\"step\">第 2 步 / 共 2 步</div><h2>连接家庭 Wi-Fi</h2><p class=\"hint\">请选择附近的 2.4 GHz Wi-Fi。凭据只保存在本设备 NVS 中。</p>"
"<label>附近 Wi-Fi<select id=\"nets\" onchange=\"pickNetwork()\"><option>正在扫描…</option></select></label><button id=\"rb\" onclick=\"scanNetworks()\">重新扫描</button>"
"<label id=\"manual\" style=\"display:none\">Wi-Fi 名称（SSID）<input id=\"s\" maxlength=\"32\" autocomplete=\"off\"></label><label>Wi-Fi 密码<input id=\"p\" type=\"password\" maxlength=\"63\" autocomplete=\"new-password\"></label>"
"<button id=\"sb\" onclick=\"go()\">保存并开始连接</button><p id=\"m\" class=\"msg\"></p><p id=\"link\" class=\"msg\"></p></section><p class=\"fallback\">若本页未自动打开，请访问 http://192.168.4.1</p></div>"
"<script>let csrf='';async function parse(r){let t=await r.text(),d={};try{d=JSON.parse(t)}catch(e){d={message:t}}if(!r.ok)throw Error(d.message||('HTTP '+r.status));return d}"
"async function loginNow(){lb.disabled=true;lm.textContent='正在验证…';try{let d=await parse(await fetch('/api/session',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({username:u.value,password:a.value})}));"
"csrf=d.csrf;login.style.display='none';setup.style.display='block';await scanNetworks()}catch(e){lm.textContent=e.message}finally{lb.disabled=false}}"
"function pickNetwork(){let o=nets.selectedOptions[0];if(!o)return;if(o.dataset.manual){manual.style.display='block';s.value='';s.focus()}else{manual.style.display='none';s.value=o.value;p.focus()}}"
"async function scanNetworks(){rb.disabled=true;m.textContent='正在扫描附近 Wi-Fi…';try{let d=await parse(await fetch('/api/wifi/scan'));nets.textContent='';"
"for(let n of d.networks){let o=document.createElement('option');o.value=n.ssid;o.textContent=n.ssid+'  '+n.rssi+' dBm'+(n.secure?'  🔒':'  开放');nets.appendChild(o)}"
"let o=document.createElement('option');o.value='';o.textContent='隐藏网络 / 手动输入';o.dataset.manual='1';nets.appendChild(o);if(d.networks.length){nets.selectedIndex=0}else{nets.selectedIndex=nets.options.length-1}pickNetwork();m.textContent=d.networks.length?'已找到 '+d.networks.length+' 个网络':'未找到网络，请重试或手动输入'}"
"catch(e){nets.innerHTML='<option value=\"\">隐藏网络 / 手动输入</option>';nets.firstChild.dataset.manual='1';pickNetwork();m.textContent=e.message}finally{rb.disabled=false}}"
"async function waitConnected(){for(let i=0;i<35;i++){await new Promise(r=>setTimeout(r,1000));let d=await parse(await fetch('/api/provision/status',{cache:'no-store'}));"
"if(d.state===2&&d.management_url){m.textContent='Wi-Fi 已连接，后台地址：'+d.management_url;link.innerHTML='若未自动跳转，请打开 <a href=\"'+d.management_url+'\">'+d.management_url+'</a>';"
"setTimeout(()=>{location.href=d.management_url},1500);return}if(d.state===3)throw Error('Wi-Fi 连接失败，请检查密码后重试')}throw Error('连接超时，配网热点将继续保留')}async function go(){sb.disabled=true;link.textContent='';try{m.textContent='正在验证 Wi-Fi 密码并获取后台地址…';"
"let d=await parse(await fetch('/api/provision',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify({ssid:s.value,password:p.value})}));"
"m.textContent=d.message;await waitConnected()}catch(e){m.textContent=e.message;sb.disabled=false}}"
"async function boot(){try{let d=await parse(await fetch('/api/session',{cache:'no-store'}));if(!d.auth_enabled){csrf=d.csrf;login.style.display='none';setup.style.display='block';await scanNetworks()}}catch(e){lm.textContent=e.message}}"
"a.addEventListener('keydown',e=>{if(e.key==='Enter')loginNow()});p.addEventListener('keydown',e=>{if(e.key==='Enter')go()});boot()</script></body></html>";
